{
  "items": [
    {
      "name": "Orthonormal.inner_finsupp_eq_sum_left",
      "type": " {𝕜 : Type u_1} {E : Type u_2} [RCLike 𝕜] [SeminormedAddCommGroup E] [InnerProductSpace 𝕜 E] {ι : Type u_4} {v : ι → E} (hv : Orthonormal 𝕜 v) (l₁ l₂ : ι →₀ 𝕜) : inner 𝕜 ((Finsupp.linearCombination 𝕜 v) l₁) ((Finsupp.linearCombination 𝕜 v) l₂) = l₁.sum fun i y => (starRingEnd 𝕜) y * l₂ i",
      "module": "Mathlib.Analysis.InnerProductSpace.Orthonormal"
    },
    {
      "name": "Orthonormal.inner_finsupp_eq_sum_right",
      "type": " {𝕜 : Type u_1} {E : Type u_2} [RCLike 𝕜] [SeminormedAddCommGroup E] [InnerProductSpace 𝕜 E] {ι : Type u_4} {v : ι → E} (hv : Orthonormal 𝕜 v) (l₁ l₂ : ι →₀ 𝕜) : inner 𝕜 ((Finsupp.linearCombination 𝕜 v) l₁) ((Finsupp.linearCombination 𝕜 v) l₂) = l₂.sum fun i y => (starRingEnd 𝕜) (l₁ i) * y",
      "module": "Mathlib.Analysis.InnerProductSpace.Orthonormal"
    },
    {
      "name": "Polynomial.sum_sq_norm_coeff_eq_circleAverage",
      "type": " (p : Polynomial ℂ) : ∑ i ∈ p.support, ‖p.coeff i‖ ^ 2 = Real.circleAverage (fun θ => ‖Polynomial.eval θ p‖ ^ 2) 0 1",
      "module": "Mathlib.Analysis.Polynomial.Fourier"
    },
    {
      "name": "Polynomial.mahlerMeasure_le_sqrt_sum_sq_norm_coeff",
      "type": " (p : Polynomial ℂ) : p.mahlerMeasure ≤ √(∑ i ∈ p.support, ‖p.coeff i‖ ^ 2)",
      "module": "Mathlib.Analysis.Polynomial.MahlerMeasure"
    }
  ]
}
